function parseCookies(header) {
  // "a=1; b=2" -> { a: "1", b: "2" }. Values are URI-decoded; only the FIRST
  // "=" separates name from value (values may contain "="); parts without an
  // "=" are ignored; a missing/empty header gives {}.
  const out = {};
  if (!header) {
    return out;
  }
  for (const part of header.split("; ")) {
    const eq = part.indexOf("=");
    if (eq === -1) {
      continue;
    }
    out[part.slice(0, eq)] = decodeURIComponent(part.slice(eq + 1));
  }
  return out;
}

module.exports = { parseCookies };

