const { execFileSync } = require("node:child_process");
const fs = require("node:fs");

const IMPL = "cookies.js";
const MUTANTS = [
  // only the first "=" may split - this truncates values containing "="
  ['    out[part.slice(0, eq)] = decodeURIComponent(part.slice(eq + 1));',
   '    out[part.slice(0, eq)] = decodeURIComponent(part.split("=")[1]);'],
  // decoding dropped
  ['    out[part.slice(0, eq)] = decodeURIComponent(part.slice(eq + 1));',
   '    out[part.slice(0, eq)] = part.slice(eq + 1);'],
  // "=-less" parts get an empty entry instead of being ignored
  ['    if (eq === -1) {\n      continue;\n    }',
   '    if (eq === -1) {\n      out[part] = "";\n      continue;\n    }'],
];

function runTests() {
  try {
    execFileSync(process.execPath, ["--test", "test_cookies.js"], { stdio: "inherit" });
    return 0;
  } catch {
    return 1;
  }
}

const src = fs.readFileSync(IMPL, "utf8");
for (const [old] of MUTANTS) {
  if (src.split(old).length - 1 !== 1) {
    console.error(`protected implementation file ${IMPL} was modified - anchor not found exactly once: ${JSON.stringify(old)}`);
    process.exit(1);
  }
}

if (runTests() !== 0) {
  console.error("model tests FAILED against the correct implementation");
  process.exit(1);
}

let failed = false;
try {
  for (let i = 0; i < MUTANTS.length; i++) {
    fs.writeFileSync(IMPL, src.replace(MUTANTS[i][0], MUTANTS[i][1]));
    if (runTests() === 0) {
      console.error(`mutation ${i + 1} SURVIVED: the tests do not verify the required behavior`);
      failed = true;
      break;
    }
  }
} finally {
  fs.writeFileSync(IMPL, src);
}
if (failed) process.exit(1);
console.log(`PASS (killed all ${MUTANTS.length} mutants)`);

