const test = require("node:test");
const assert = require("node:assert");
const { parseCookies } = require("./cookies");

test("plain multi-cookie header", () => {
  assert.deepStrictEqual(parseCookies("a=1; b=2"), { a: "1", b: "2" });
});

test("value containing equals signs stays whole", () => {
  assert.deepStrictEqual(parseCookies("token=abc=def=="), { token: "abc=def==" });
});

test("values are URI-decoded", () => {
  assert.deepStrictEqual(parseCookies("name=Ada%20Lovelace"), { name: "Ada Lovelace" });
});

test("parts without an equals are ignored", () => {
  assert.deepStrictEqual(parseCookies("a=1; Secure; b=2"), { a: "1", b: "2" });
});

test("empty and missing headers give empty objects", () => {
  assert.deepStrictEqual(parseCookies(""), {});
  assert.deepStrictEqual(parseCookies(undefined), {});
});

