const test = require("node:test");
const assert = require("node:assert");
const { parseCookies } = require("./cookies");

test("returns an object", () => {
  assert.strictEqual(typeof parseCookies("a=1"), "object");
});

test("simple pair parsed", () => {
  assert.strictEqual(parseCookies("a=1").a, "1");
});

test("empty header gives empty object", () => {
  assert.deepStrictEqual(parseCookies(""), {});
});

test("two cookies give two keys", () => {
  assert.strictEqual(Object.keys(parseCookies("a=1; b=2")).length, 2);
});
